data.setupCode:
// A chain of up to 48 masses joined by springs; mass 0 is the head that follows the mouse.
// World units: y in -0.5..0.5 (screen height = 1), x scaled by the screen aspect.
const N = 48;
state.N = N;
state.p = new Float32Array(N * 2);   // positions
state.v = new Float32Array(N * 2);   // velocities
for (let i = 0; i < N; i++) {
  state.p[2 * i] = 0;
  state.p[2 * i + 1] = 0.3 - i * 0.02;
}
state.head = [0, 0.3];
state.idle = 99;                     // seconds since the mouse last moved
state.out = new Float32Array(N * 4); // -> dataTexture(N x 1): x, y, radius, t (0 head .. 1 tip)

data.code:
// Spring chain (a tentacle) that follows the mouse.
// - state keeps positions and velocities between frames.
// - The head eases toward the target with damp(current, target, rate): frame-rate
//   independent exponential smoothing.
// - The chain is integrated with semi-implicit Euler in fixed 1/240 s sub-steps, so
//   stiff springs stay stable and the motion is the same at 30, 60 or 144 fps.
const { N, p, v, out } = state;
const n = clamp(Math.round(params['Segments'] ?? 28), 4, N);
const rest = (params['Length'] ?? 0.7) / (n - 1);
// spring stiffness per unit mass, scaled with the segment count so the chain keeps its
// overall stretchiness when Segments changes (shorter springs must be stiffer)
const k = (params['Stiffness'] ?? 300) * (n - 1) / 8;
const c = params['Damping'] ?? 5;          // damping of the relative velocity along each spring
const g = params['Gravity'] ?? 0.2;
const wiggle = params['Wiggle'] ?? 0.8;
const aspect = resolution[0] / Math.max(1, resolution[1]);

// Target: the mouse while it moves; after 2 s idle, a slow figure-eight
const mx = (mouse[0] - 0.5) * aspect, my = mouse[1] - 0.5;
const moved = state.mx !== undefined && Math.hypot(mx - state.mx, my - state.my) > 1e-4;
state.mx = mx; state.my = my;
state.idle = moved ? 0 : state.idle + dt;
const w = clamp((state.idle - 2) / 1.5);
const tx = mix(mx, 0.36 * aspect * Math.sin(time * 0.55), w);
const ty = mix(my, 0.24 * Math.sin(time * 1.1) + 0.05, w);
const follow = params['Follow'] ?? 10;
state.head[0] = damp(state.head[0], tx, follow);
state.head[1] = damp(state.head[1], ty, follow);

const steps = Math.min(40, Math.max(1, Math.ceil(dt / (1 / 240))));
const h = dt / steps;
const air = Math.exp(-1.5 * h);           // a little air drag
const hx0 = p[0], hy0 = p[1];
for (let s = 1; s <= steps; s++) {
  // the head is pinned: interpolate it along this frame's motion
  p[0] = mix(hx0, state.head[0], s / steps);
  p[1] = mix(hy0, state.head[1], s / steps);
  for (let i = 1; i < n; i++) {
    let ax = 0, ay = -g;
    for (const j of [i - 1, i + 1]) {
      if (j >= n) continue;
      const dx = p[2 * j] - p[2 * i], dy = p[2 * j + 1] - p[2 * i + 1];
      const d = Math.hypot(dx, dy) + 1e-6, ux = dx / d, uy = dy / d;
      const rv = (v[2 * j] - v[2 * i]) * ux + (v[2 * j + 1] - v[2 * i + 1]) * uy;
      const f = k * (d - rest) + c * rv;
      ax += f * ux;
      ay += f * uy;
    }
    // a travelling sideways wave makes it swim
    const px = p[2 * i] - p[2 * (i - 1)], py = p[2 * i + 1] - p[2 * (i - 1) + 1];
    const pl = Math.hypot(px, py) + 1e-6;
    const sw = wiggle * 3 * Math.sin(time * 5 - i * 0.45) * (i / n);
    ax += -py / pl * sw;
    ay += px / pl * sw;
    v[2 * i] = (v[2 * i] + ax * h) * air;
    v[2 * i + 1] = (v[2 * i + 1] + ay * h) * air;
  }
  for (let i = 1; i < n; i++) {
    p[2 * i] += v[2 * i] * h;
    p[2 * i + 1] += v[2 * i + 1] * h;
  }
}
// Unused masses trail the tip, so changing Segments never snaps
for (let i = n; i < N; i++) {
  p[2 * i] = p[2 * (n - 1)];
  p[2 * i + 1] = p[2 * (n - 1) + 1];
  v[2 * i] = v[2 * i + 1] = 0;
}

// Output: radius tapers from the head (with a little bulb) to the tip
const thick = params['Thickness'] ?? 0.04, taper = params['Taper'] ?? 0.85;
for (let i = 0; i < N; i++) {
  const t = Math.min(i, n - 1) / (n - 1);
  const r = thick * (1 - taper * t) * (1 + 0.35 * Math.exp(-t * 18));
  out.set([p[2 * i], p[2 * i + 1], r, t], 4 * i);
}
return { chain: dataTexture(out, N, 1, 4), count: float(n), head: vec2(state.head) };

SpringRibbon.customGLSL:
// @node springRibbon
// @title Spring Ribbon
// @category custom
// @description Draws the JS spring chain (N x 1 data texture: x, y, radius, t) as one smooth SDF: tapered capsules between consecutive masses, smooth-unioned. Shaded as a glossy tube (normal from the SDF gradient and the tube profile), coloured along its length with ring bands, a soft drop shadow, a pool of light under the head and a dark studio backdrop. Returns color.
float sr_smin(float a, float b, float k) {
    float h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);
    return mix(b, a, h) - k * h * (1.0 - h);
}

// Distance to the chain; t = position along it (0 head .. 1 tip), r = local radius
float sr_map(vec2 p, sampler2D chain, float count, out float t, out float r) {
    float d = 1e5;
    float best = 1e5;
    t = 0.0;
    r = 0.01;
    vec4 a = texelFetch(chain, ivec2(0, 0), 0);
    for (int i = 1; i < 48; i++) {
        if (float(i) >= count) break;
        vec4 b = texelFetch(chain, ivec2(i, 0), 0);
        vec2 pa = p - a.xy;
        vec2 ba = b.xy - a.xy;
        float h = clamp(dot(pa, ba) / max(dot(ba, ba), 1e-8), 0.0, 1.0);
        float rr = mix(a.z, b.z, h);
        float dc = length(pa - ba * h);
        float di = dc - rr;
        if (di < best) {
            best = di;
            t = mix(a.w, b.w, h);
            r = rr;
        }
        d = sr_smin(d, di, 0.012);
        a = b;
    }
    return d;
}

vec3 springRibbon(vec2 uv, sampler2D chain, float count, vec2 head, vec3 colorA, vec3 colorB, float gloss, float shadow) {
    float aspect = u_resolution.x / max(u_resolution.y, 1.0);
    vec2 p = (uv - 0.5) * vec2(aspect, 1.0);
    float px = 1.0 / max(u_resolution.y, 1.0);

    // Backdrop: dark studio sweep with a faint dot grid
    vec3 bg = mix(vec3(0.06, 0.065, 0.08), vec3(0.24, 0.25, 0.28), smoothstep(-0.6, 0.6, p.y));
    bg *= 1.0 - 0.3 * dot(p, p);
    vec2 gq = fract(p * 24.0) - 0.5;
    bg += vec3(0.025) * (1.0 - smoothstep(0.03, 0.07, length(gq)));

    // A pool of light under the head (head = the JS node's vec2 output)
    vec2 dh = p - head;
    bg += colorA * 0.12 * exp(-dot(dh, dh) * 10.0);

    // Soft drop shadow (the light is up-left)
    float st, sr;
    float ds = sr_map(p - vec2(0.025, -0.04), chain, count, st, sr);
    bg *= 1.0 - shadow * 0.7 * (1.0 - smoothstep(-0.03, 0.06, ds));

    float t, r;
    float d = sr_map(p, chain, count, t, r);
    if (d > 0.02) return bg;

    // Normal: SDF gradient (x, y) and a round tube profile (z)
    float e = 0.0015;
    float t1, r1;
    vec2 grad = vec2(sr_map(p + vec2(e, 0.0), chain, count, t1, r1) - d,
                     sr_map(p + vec2(0.0, e), chain, count, t1, r1) - d) / e;
    float depth = clamp(-d / max(r, 1e-3), 0.0, 1.0);
    float nz = sqrt(1.0 - (1.0 - depth) * (1.0 - depth));
    vec3 n = normalize(vec3(normalize(grad + 1e-6) * (1.0 - depth), nz));

    vec3 L = normalize(vec3(-0.45, 0.6, 0.65));
    vec3 V = vec3(0.0, 0.0, 1.0);
    vec3 H = normalize(L + V);
    float diff = max(dot(n, L), 0.0);
    float spec = pow(max(dot(n, H), 0.0), 48.0) * gloss * 1.2;
    float fres = pow(1.0 - max(n.z, 0.0), 3.0);

    // Colour along the length, ring bands, a darker underside
    vec3 base = mix(colorA, colorB, smoothstep(0.0, 1.0, t));
    float bands = 0.82 + 0.18 * smoothstep(-0.2, 0.6, sin(t * count * 3.14159));
    base *= bands;
    vec3 col = base * (0.25 + 1.1 * diff);
    col += vec3(1.0, 0.97, 0.92) * spec;
    col += mix(colorB, vec3(0.6, 0.8, 1.0), 0.5) * fres * 0.55;

    float a = 1.0 - smoothstep(-px, px, d);
    return mix(bg, col, a);
}
